func _update_reinforcements(delta: float) -> void:
	if mode != "playing" or stage != 2 or reinforcement_next >= REINFORCEMENT_COUNT:
		return
	if linear.enabled and "river" not in linear.opened:
		return
	reinforcement_wait = maxf(0.0, reinforcement_wait - delta)
	if reinforcement_wait > 0.0 or alive_guard_count() >= MAX_ALIVE_GUARDS:
		return
	var entry: Vector3 = REINFORCEMENT_ENTRIES[reinforcement_next]
	if not _reinforcement_entry_safe(entry):
		reinforcement_wait = 0.5
		return
	var guard := _spawn_guard("wave_%d" % reinforcement_next, entry, Vector3(74, 0.08, 30))
	if guard == null:
		return
	guard.hear_shot(Vector3(74, 0.08, 30))
	reinforcement_next += 1
	reinforcement_pending = REINFORCEMENT_COUNT - reinforcement_next
	reinforcement_wait = REINFORCEMENT_WAVE_DELAY if reinforcement_next % 2 == 0 else REINFORCEMENT_INTERVAL
	if reinforcement_pending == 0:
		reinforcement_wait = 0.0
	_save_checkpoint()

func _snapshot() -> Dictionary:
	var active: Dictionary = {}
	for guard in guards:
		if is_instance_valid(guard) and guard.state != "dead":
			active[guard.guard_id] = guard.encounter_snapshot()
	return {"version": 2, "player": player.snapshot(), "story": story.snapshot(), "stage": stage, "defeated": defeated.duplicate(), "kills": kills, "elapsed": elapsed, "yard": reached_yard,
		"linear": linear.snapshot(), "encounter": {"expanded": expanded_encounter, "next": reinforcement_next, "wait": reinforcement_wait, "active": active}}

func _read_save() -> Dictionary:
	if not FileAccess.file_exists(save_path):
		return {}
	var file := FileAccess.open(save_path, FileAccess.READ)
	if file == null:
		return {}
	var parser := JSON.new()
	if parser.parse(file.get_as_text()) != OK:
		return {}
	var result = parser.data
	if not result is Dictionary or result.get("version") != 2 or not result.get("player") is Dictionary:
		return {}
	if not story.valid(result.get("story")):
		return {}
	if result.has("linear") and not linear.valid_snapshot(result.linear):
		return {}
	if not _whole_number(result.get("stage"), 0, 2):
		return {}
	if not result.get("defeated") is Dictionary or not result.get("yard") is bool:
		return {}
	for identifier in result.defeated:
		if (identifier not in INITIAL_GUARDS and identifier not in ["wave_0", "wave_1", "wave_2", "wave_3"]) or result.defeated[identifier] != true:
			return {}
	if not _whole_number(result.get("kills"), 0, 9) or int(result.kills) != result.defeated.size():
		return {}
	if not _valid_encounter(result):
		return {}
	if not _number_between(result.get("elapsed"), 0, 10000000):
		return {}
	var saved_player: Dictionary = result.player
	for key in ["position", "magazines", "reserves"]:
		if not saved_player.get(key) is Array or saved_player[key].size() != (3 if key == "position" else 2):
			return {}
	if not _number_between(saved_player.position[0], 4.4, 83.6) or not _number_between(saved_player.position[1], -0.1, 6) or not _number_between(saved_player.position[2], 4.4, 91.6):
		return {}
	if not _number_between(saved_player.get("health"), 0.1, 100) or not _number_between(saved_player.get("yaw"), -100000, 100000) or not _whole_number(saved_player.get("weapon"), 0, 1):
		return {}
	for index in 2:
		if not _whole_number(saved_player.magazines[index], 0, Player.WEAPONS[index].capacity) or not _whole_number(saved_player.reserves[index], 0, 1000):
			return {}
	return result

func talk(id: String) -> void:
	match id:
		"scout":
			if not met_scout:
				show_dialog(id, "姜岚", "沈砚，林场的电报房扣下了搜山名册。陆山送信时受了伤，也被关在那里。名单关系着密营和山下接济我们的乡亲。\n先问问前面木棚里的林师傅，再进电报房。我守住回山的路，你把人和名单带回来。", [
					{"label": "知道了。名单和陆山，都带回来。", "action": "brief"},
					{"label": "问清楚电报房和撤离路线", "action": "route"}])
			else:
				show_dialog(id, "姜岚", "穿过木墙缺口，先突破检查口，再沿木料巷往北。清掉守卫才能打开栅门。取名单、拉总闸，接上陆山绕电报房北侧去渡口。别丢下他。", [{"label": "继续行动", "action": "close"}])
		"logger":
			if supply_choice == "none":
				show_dialog(id, "林守义", "陆山在电报房西北角，腿上有伤。昨晚他还替我捎话，说山上的孩子缺棉衣……今天就没能走出那扇门。\n我这儿有一卷干净布，还有藏下的十发步枪弹。你先带哪一样？剩下的留给接应的人。", [
					{"label": "拿绷带，给陆山治伤", "action": "medicine"},
					{"label": "拿十发步枪弹", "action": "ammunition"},
					{"label": "先不拿，等会儿再来", "action": "close"}])
			else:
				show_dialog(id, "林守义", "电报房的门没上锁。桌后的总闸连着电话中继，拉下来能拖住他们。运材场矮箱上还有个医药包；别让陆山一个人留在里面。", [{"label": "谢谢。你也先隐蔽。", "action": "close"}])
		"lu":
			if not recruited:
				var options: Array = []
				if bandages > 0:
					options.append({"label": "消耗一卷绷带，包扎后一起走", "action": "rescue_treat"})
				options.append({"label": "先带你离开，慢慢跟着我", "action": "rescue"})
				options.append({"label": "先在这里隐蔽，我处理电报房", "action": "close"})
				show_dialog(id, "陆山", "名册就在桌上。第三页那个卖豆腐的，上回给我们多塞了两块……他还有两个孩子。别把名字落下。\n我还能走。你慢一点，到拐角等我一下。", options)
			else:
				var options: Array = [{"label": "跟紧我", "action": "follow"}, {"label": "在这里等候，我先探路", "action": "wait"}]
				if not people.lu.treated and bandages > 0:
					options.append({"label": "用绷带处理伤口", "action": "treat"})
				show_dialog(id, "陆山", "听你的。我的脚步可能慢一些，走到拐角时记得回头看看。" if not people.lu.treated else "伤口扎稳了，我能跟上。名单交回去，乡亲们就多一分转移的时间。", options)

func snapshot() -> Dictionary:
	var lu: CharacterBody3D = people.lu
	return {"briefed": met_scout, "choice": supply_choice, "letter": read_letter, "supply": supply_taken, "recruited": recruited, "door": door_open, "bandages": bandages, "lu_position": [lu.position.x, lu.position.y, lu.position.z], "following": lu.following, "treated": lu.treated, "moments_seen": moments.seen.duplicate() if is_instance_valid(moments) else []}

func valid(data: Variant) -> bool:
	if not data is Dictionary:
		return false
	if not StoryMoments.valid_flags(data.get("moments_seen", [])):
		return false
	for key in ["briefed", "letter", "supply", "recruited", "door", "following", "treated"]:
		if not data.get(key) is bool:
			return false
	if (data.following or data.treated) and not data.recruited:
		return false
	if data.get("choice") not in ["none", "medicine", "ammunition"] or not main._whole_number(data.get("bandages"), 0, 3):
		return false
	if not data.get("lu_position") is Array or data.lu_position.size() != 3:
		return false
	return main._number_between(data.lu_position[0], 4.4, 83.6) and main._number_between(data.lu_position[1], -0.1, 6) and main._number_between(data.lu_position[2], 4.4, 91.6)

func update(delta: float) -> void:
	if not enabled or main.mode != "playing":
		return
	if not contact_started and main.story.met_scout and main.player.position.x > 24:
		contact_started = true
		main.notify("前方检查口有岗哨。压低身子，借沙袋接近。", 4)
	if "river" not in opened or main.stage != 2 or not main.story.recruited:
		return
	if not main.story.people.lu.following or main.player.position.distance_to(main.EVAC) > 10 or main.story.people.lu.position.distance_to(main.EVAC) > 6:
		return
	if not extraction_started:
		extraction_started = true
		main.notify("陆山正在解缆！守住渡口，留意南侧追兵。", 5)
		main._save_checkpoint()
	if extraction_remaining > 0:
		extraction_remaining = maxf(0, extraction_remaining - delta)
		if extraction_remaining == 0:
			main.notify("陆山：缆绳解开了！到船边按 E，一起走！", 6)
			main._save_checkpoint()

func _process(delta: float) -> void:
	if not is_instance_valid(main):
		return
	var active: bool = main.mode == "playing"
	river_audio.stream_paused = not active
	radio_audio.stream_paused = not active
	switch_audio.stream_paused = not active
	if not active:
		return
	if last_stage != main.stage:
		if last_stage < 2 and main.stage == 2:
			radio_audio.stop()
			switch_audio.play()
			_say("power", "陆山：灯灭了……他们会回来，别在门口停。")
		last_stage = main.stage
	remaining = maxf(0, remaining - delta)
	if remaining > 0:
		return
	caption = ""
	silence = maxf(0, silence - delta)
	if silence > 0:
		return
	var story: RefCounted = main.story
	var player_at: Vector3 = main.player.position
	var lu: CharacterBody3D = story.people.lu
	if story.recruited and main.stage == 2:
		if player_at.distance_to(main.EVAC) < 12 and lu.position.distance_to(main.EVAC) < 14:
			if _say("river", "陆山：听见水了。把名单揣进衣服里，别让它湿了。"):
				return
		if lu.following and lu.position.distance_to(player_at) > 16:
			if _say("falling_behind", "陆山：等一下……这条腿跟不上了。"):
				return
		if player_at.x > 66 and player_at.z < 31 and lu.position.distance_to(player_at) < 7:
			if _say("crossing", "陆山：从前这条路，我闭着眼也走得过。"):
				return
	if not story.met_scout:
		return
	if "contact" not in seen:
		for guard in main.guards:
			if is_instance_valid(guard) and guard.state == "combat" and player_at.distance_to(guard.position) < 28:
				_say("contact", "沈砚：有人！先找掩护。")
				return
	if story.supply_choice == "medicine" and player_at.distance_to(story.LOGGER) < 7:
		if _say("cloth", "林守义：这是家里剩下的干布……给他扎紧些。"):
			return
	if player_at.z < 79 and player_at.z > 62:
		_say("departure", "沈砚：先把人带出去。名单上的名字，一个也不能丢。")

func _physics_process(delta: float) -> void:
	if state == "dead":
		if main.mode == "playing":
			model.animate_death(delta)
		return
	if main.mode != "playing":
		return
	if main.linear != null and not main.linear.can_guard_act(guard_id):
		return
	var previous_yaw := rotation.y
	var player_position: Vector3 = main.player.global_position
	var distance := global_position.distance_to(player_position)
	var visible_player := can_see_player()
	if visible_player:
		if state == "patrol":
			main.notify("岗哨发现了你！", 2.0)
			fire_timer = 1.4 + float(absi(guard_id.hash()) % 4) * 0.12
		state = "combat"
		last_seen = player_position
		sight_memory = 6.0
	else:
		sight_memory = maxf(0, sight_memory - delta)
		if state == "combat" and sight_memory < 4:
			state = "search"
		if state == "search" and sight_memory <= 0:
			state = "patrol"
	var target := patrol_target if state == "patrol" else last_seen
	if state == "patrol" and global_position.distance_to(target) < 1.2:
		patrol_target = spawn_position if patrol_target != spawn_position else patrol_endpoint
	path_timer -= delta
	if path_timer <= 0:
		route = main.world.path(global_position, target)
		route_index = 1 if route.size() > 1 else 0
		path_timer = 0.6
	var direction := Vector3.ZERO
	if not (visible_player and distance < 17) and route_index < route.size():
		var to_point := route[route_index] - global_position
		to_point.y = 0
		if to_point.length() < 0.7:
			route_index += 1
		else:
			direction = to_point.normalized()
	var facing := (player_position - global_position) if visible_player else direction
	facing.y = 0
	if facing.length() > 0.05:
		rotation.y = lerp_angle(rotation.y, atan2(-facing.x, -facing.z), delta * 7)
	velocity.x = direction.x * (2.2 if state != "patrol" else 1.3)
	velocity.z = direction.z * (2.2 if state != "patrol" else 1.3)
	velocity.y = -0.2 if is_on_floor() else velocity.y - delta * 20
	move_and_slide()
	stride += delta * direction.length() * 7
	model.set_motion_context(false, angle_difference(previous_yaw, rotation.y) / maxf(delta, 0.001), visible_player)
	model.animate(delta, direction.length() * 1.8)
	fire_timer -= delta
	if visible_player and distance < 26 and fire_timer <= 0:
		fire_timer = 2.0 + float(absi(guard_id.hash()) % 4) * 0.12
		shots_fired += 1
		model.fire()
		# The first shot warns; subsequent deliberate shots alternate with
		# suppression. Extra guards add pressure without six perfect hits at once.
		var aimed_hit := shots_fired % (3 if distance > 12.0 else 2) == 0
		var shot_target := player_position + Vector3.UP * 1.2
		if not aimed_hit:
			var side := (player_position - global_position).cross(Vector3.UP).normalized()
			shot_target += side * (0.8 if shots_fired % 2 == 0 else -0.8) + Vector3.UP * 0.25
		main.guard_shot(global_position + Vector3.UP * 1.35, shot_target)
		if aimed_hit:
			main.player.take_damage(7.0 if distance > 12 else 9.0)
